INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_ADJECTIVE','Urgal');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_AFTERTASTE','Aftertaste - {1_Num} turns remaining');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_ATTACKED_1','You came all this way. Now stay.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_BUILDING','Brewing Stand');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_BUILDING_HELP','Replaces Barracks. 75 Production, 1 maintenance and the active Barracks training XP (15 on the supported baseline). +10% Production toward eligible land melee units, including custom melee combat classes. Does not create Strength Potions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_BUILDING_PEDIA','The Brewing Stand is a place of preparation. Bottles sit beside weapons, supplies are checked and the next charge is planned. Its military workshops train the army; the civilization''s rare Strength Potions remain tied to Era progression.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_BUILDING_STRATEGY','Build Brewing Stands to prepare the army before committing a potion. They retain Barracks companion benefits and help train only eligible melee land units. They never generate potions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_CHASER','Pot Chaser');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_CHASER_HELP','While affected by Strength II, kills restore 15 HP up to maximum health. This veteran ability is retained on upgrade; it has no effect outside Strength II.');
