INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_CITY_7','Hotbar Heights');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_CITY_8','No Return');
