INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_CIV','The Urgal');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_CIV5_HEADING_1','The Strength Kit');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_CIV5_TEXT_1','The Urgal takes its identity from the Strength potion kit of MCPVP Hardcore Games. Ordinary equipment could become terrifying for a brief encounter: drink, close the distance and press the advantage before it vanished. In this civilization that decision becomes an empire-wide military commitment. Potions arrive only with the passing of Eras. Every wasted charge is gone forever.[NEWLINE][NEWLINE]The Feast is the gathering point of an army that spends most of its time preparing. Brewing tables and barracks fill with equipment, roads are laid, and commanders search for the moment when retreat becomes impossible. The warning is simple: Urgal drank Strength. Run.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_CIV_PEDIA','The Urgal takes its identity from the Strength potion kit of MCPVP Hardcore Games. Ordinary equipment could become terrifying for a brief encounter: drink, close the distance and press the advantage before it vanished. In this civilization that decision becomes an empire-wide military commitment. Potions arrive only with the passing of Eras. Every wasted charge is gone forever.[NEWLINE][NEWLINE]The Feast is the gathering point of an army that spends most of its time preparing. Brewing tables and barracks fill with equipment, roads are laid, and commanders search for the moment when retreat becomes impossible. The warning is simple: Urgal drank Strength. Run.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_DAWN','Urgal, the battlefield is quiet. Your people are gathering iron, sharpening blades and preparing the roads.[NEWLINE][NEWLINE]Your strength is not endless. Each Era brings a single bottle, and each bottle offers only a handful of turns in which the world must fear your army. Build your Brewing Stands. Train your Rushers. Wait until the enemy has nowhere left to run.[NEWLINE][NEWLINE]Then drink.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_DEFEAT_1','Should have saved one more bottle.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_DRANK','Strength II activated for {1_Num} turns on {2_Num} eligible units. Run.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_DRINK','DRINK STRENGTH II');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_EMPTY','NO POTIONS');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_EXPIRED','Strength II has expired. Aftertaste prevents another potion for 2 turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_FRIENDLY_1','The stand is ready. For now, the bottles stay closed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_GAIN','A new Era grants {1_Num} Strength Potion(s). Stockpile: {2_Num}.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_GREETING_1','Keep your distance. I have not decided whether this fight is worth a potion.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_HOSTILE_1','You are standing too close.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_INVENTORY','Strength Potions: {1_Num}');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_LEADER','Urgal');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_LEADER_PEDIA','Urgal represents the aggressive Hardcore Games player who understands that preparation matters as much as the charge. He carries no permanent supernatural strength. His advantage is timing: a prepared force, a limited bottle and an opponent who has already committed. His veteran Rushers pursue the retreating enemy, recovering after successful kills while the potion lasts.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_NEUTRAL_1','What brings you to the Feast?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_NO_ARMY','No eligible units');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_PEACE_1','We will both need time to prepare.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_READY','Army ready');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_RECOVERY','Pot Chaser - Strength II recovery');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_RECOVERY_HELP','Killing an enemy unit heals 15 HP, up to maximum health. Temporary: requires Pot Chaser and active Strength II.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SHORT','The Urgal');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_1','Refill');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_10','The Brewer');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_2','Hotbar');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_3','Tracker');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_4','Vial');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_5','Feast Runner');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_6','Iron Hand');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_7','Last Bottle');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_8','Rush Scout');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_SPY_9','Night Chase');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_STRATEGY','Prepare your army and roads before drinking. Use a scarce Strength Potion when the enemy cannot disengage, then attack during the short window. Brewing Stands help train eligible melee units. Rushers require no Iron and retain Pot Chaser on upgrade. Retreating enemies, mobile armies and cheap screens can waste your potion. The civilization receives no special economic or scientific boost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_STRENGTH','Strength II');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_STRENGTH_HELP','+50% attacking Combat Strength against units during the current potion window. No defensive bonus. City attacks are unchanged. Applies only to the melee land units present when the potion was consumed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_TOOLTIP','Potion of Strength II[NEWLINE]Consume 1 Strength Potion to empower eligible melee land units you currently own for {1_Num} turns. +50% attacking Combat Strength against units; no defensive or city bonus. Ranged, naval, air, reconnaissance, siege, helicopter and civilian units are excluded. Units created afterwards do not receive the effect. Cannot stack. After expiration, Aftertaste blocks drinking for 2 turns.[NEWLINE][NEWLINE]Current stockpile: {2_Num}.[NEWLINE]Eligible units now: {3_Num}.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_TRADE_1','A fair exchange. Keep moving.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_TRAIT','Strength II');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_TRAIT_HELP','Begin with 1 Strength Potion; gain 1 per new Era. Stockpile without a cap. Drink to give currently owned, eligible land melee units +50% attacking Combat Strength for 3/5/7/12 turns on Quick/Standard/Epic/Marathon. No defensive, city, ranged, naval or air bonus. New recruits are excluded. Potions cannot stack; 2 turns of Aftertaste block the next drink.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_UNAVAILABLE','Potion state unavailable');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_UNIT','Urgal Rusher');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_UNIT_HELP','Replaces Swordsman. 14 Combat Strength, 2 Movement, 80 Production and no Iron requirement. Pot Chaser: while affected by Strength II, killing an enemy unit heals 15 HP, up to maximum health. Pot Chaser survives upgrades.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_UNIT_PEDIA','The Rusher embodies the classic sequence: drink, rush, kill, recover and keep rushing. The unit uses the ordinary Swordsman model and upgrade path. Its distinguishing advantage is the veteran who survives to carry Pot Chaser into later Eras.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_UNIT_STRATEGY','Train a reliable Classical army without Iron. Position these slightly more expensive Swordsmen before activating Strength II. Their permanent Pot Chaser promotion rewards kills during potion windows and remains useful after upgrading.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_URGAL_HEADING_1','The Moment to Drink');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_URGAL_LIVED','The Hardcore Games');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_URGAL_NAME','Urgal');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_URGAL_SUBTITLE','The Potion Rusher');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_URGAL_TEXT_1','Urgal represents the aggressive Hardcore Games player who understands that preparation matters as much as the charge. He carries no permanent supernatural strength. His advantage is timing: a prepared force, a limited bottle and an opponent who has already committed. His veteran Rushers pursue the retreating enemy, recovering after successful kills while the potion lasts.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_URGAL_TITLES_1','Keeper of Strength II');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_URGAL_WAR_1','You have nowhere left to run.');
